from __future__ import annotations
from .canonical import content_hash,stable_id

def build(evidence,authority):
    gates={"upstream_verified":evidence["upstream_receipt"]["verified"],"custody_commitment_verified":evidence["custody_receipt"]["commitment_verified"],"air_gap_attested":evidence["air_gap_attestation"]["passed"],"submission_irreversible":evidence["submission_commitment"]["irreversible"],"token_consumed_once":evidence["consumed_token"]["used_count"]==1,"sealed_evaluation_once":evidence["sealed_result"]["evaluation_count"]==1,"future_suffix_invariant":evidence["known_time_review"]["future_suffix_sensitivity"] is False,"query_chain_verified":evidence["query_ledger"]["chain_verification"]["verified"],"custody_chain_verified":evidence["custody_ledger"]["chain_verification"]["verified"],"token_chain_verified":evidence["token_ledger"]["chain_verification"]["verified"],"transport_chain_verified":evidence["transport_ledger"]["chain_verification"]["verified"],"aggregate_only_disclosure":set(evidence["disclosure_envelope"])=={"evaluation_id","candidate_id","dataset_commitment_hash","protocol_id","decision","aggregate_metrics","baseline_comparison","release_hash"},"security_passed":evidence["security_review"]["passed"],"authority_zero":not any(authority["authority"].values())}
    body={"phase":"SAED_V4_29","version":"1.0.0","claim_class":"hidden_evaluation_air_gap_closed_reference_implementation","accepted_for_hidden_evaluation_air_gap_research_reference":all(gates.values()),"gates":gates,"candidate_decision":evidence["sealed_result"]["decision"],"evidence_hashes":{k:content_hash(v) for k,v in evidence.items()},"authority_boundary":authority,"synthetic_fixture_control_claim":True,"real_hidden_dataset_claim":False,"external_custodian_independence_claim":False,"os_air_gap_certification_claim":False,"hsm_enforcement_claim":False,"independent_replication_claim":False,"real_alpha_claim":False,"prospective_success_claim":False,"promotion_authority":False,"runtime_executable":False,"risk_allocation_authority":False,"execution_authority":False,"production_authority":False,"online_learning_authority":False,"live_trading_authority":False,"research_only":True}
    body["certificate_id"]=stable_id("hidden_evaluation_air_gap_certificate",body); body["certificate_hash"]=content_hash(body); return body

def handoff(cert):
    body={"phase":"SAED_V4_29","next_phase":"SAED_V4_30","certificate_id":cert["certificate_id"],"certificate_hash":cert["certificate_hash"],"entry_gates":{"hidden_evaluation_reference_accepted":cert["accepted_for_hidden_evaluation_air_gap_research_reference"],"one_shot_semantics_verified":cert["gates"]["token_consumed_once"],"aggregate_only_disclosure_verified":cert["gates"]["aggregate_only_disclosure"],"append_only_ledgers_verified":all(cert["gates"][k] for k in ["query_chain_verified","custody_chain_verified","token_chain_verified","transport_chain_verified"]),"authority_zero":cert["gates"]["authority_zero"],"synthetic_fixture_only":True,"research_only":True},"allowed_next_work":["independent_replication_protocol","multi_lab_package_identity","replication_lab_registration","blinded_artifact_exchange","cross_lab_hash_reconciliation","replication_disagreement_report","external_custody_evidence_attachment"],"forbidden_next_work":["reuse_hidden_evaluation_token","adaptive_final_set_tuning","promotion_authorization","runtime_compilation","risk_allocation","order_submission","production_release","online_policy_mutation"],"authority":{"promotion":False,"runtime":False,"risk_allocation":False,"execution":False,"production":False,"online_learning":False},"research_only":True}
    body["handoff_id"]=stable_id("v4_29_to_v4_30",body); body["handoff_hash"]=content_hash(body); return body
